{"cards": [{"node_code": "N_80051b1ba608c501", "definition": "研究三维空间运动机构、利用弹性变形实现运动的柔顺机构以及拓扑结构可变的变胞机构的运动学原理、构型综合与设计方法。", "boundary": "聚焦于非平面、非刚性或拓扑可变机构的几何运动学特性。涵盖空间并联/串联机构、柔性铰链与柔顺机构构型、变胞与折展机构的运动规律及自由度分析。侧重机构构型与运动传递，不涉及柔性材料本构关系、空间机构动力学控制算法或具体工程应用系统的整体集成。", "includes": ["空间连杆、并联及串联机构的运动学分析与综合", "柔顺机构、柔性铰链的构型设计与运动特性", "变胞、可重构及折展机构的拓扑变换与运动原理"], "excludes": ["柔性材料的力学性能测试或本构模型建立（归材料或力学节点）", "空间机构的动力学建模、轨迹规划或控制策略（归机械动力学或控制节点）"], "sibling_distinctions": [{"other_code": "N_68ce58830549c2a1", "rule": "本节点处理三维空间运动及非刚性/可变构型；兄弟节点处理二维平面内的刚性构件运动。"}, {"other_code": "N_4377f9d55bf41395", "rule": "本节点侧重空间构型、柔顺特性或拓扑变化；兄弟节点侧重齿轮啮合原理及常规组合机构的运动学。"}], "cross_boundary_rule": "涉及柔顺机构时，若侧重构型综合与运动学归本节点，若侧重柔性梁/板力学分析归力学节点；涉及空间机构时，若侧重运动学归本节点，若侧重动力学与控制归相应节点。"}, {"node_code": "N_bd06c582a862c317", "definition": "研究实现工件或部件在离散位置间精确分度、定位及锁紧的机构原理、结构形式及运动学设计方法。", "boundary": "聚焦于分度与定位功能的实现机制，包括间歇运动机构、定位销/面配合、锁紧机构及高精度定位原理。涵盖分度精度分析、定位方案设计及典型分度机构（如槽轮、棘轮、凸轮分度）的运动学特性。不涉及分度机构的驱动电机选型、控制系统设计或具体机床/设备的整体布局。", "includes": ["间歇运动与分度机构的运动学原理及设计", "定位元件、定位面及锁紧机构的结构形式与精度分析", "高精度定位装置的运动学综合与误差分析"], "excludes": ["分度机构的驱动系统（电机、液压）设计（归传动或控制节点）", "分度机构的控制系统、传感器集成或自动化流程（归控制或自动化节点）"], "sibling_distinctions": [{"other_code": "N_68ce58830549c2a1", "rule": "本节点侧重实现离散位置变换与锁定的功能机构；兄弟节点侧重连续运动传递或特定轨迹生成的通用机构。"}, {"other_code": "N_80051b1ba608c501", "rule": "本节点侧重平面或简单空间内的分度定位功能；兄弟节点侧重复杂空间构型、柔顺或拓扑可变机构。"}], "cross_boundary_rule": "涉及分度机构时，若侧重运动学原理与结构归本节点，若侧重驱动与传动归传动节点；涉及定位时，若侧重机械结构归本节点，若侧重测量与反馈归测量或控制节点。"}]}
